-- ============================================================================
-- Migration 018: Clean Auto-generated / Demo / Sample Stitch Counts Safely
-- Purpose:
--   Sets stitch_count, stitch_count_front, stitch_count_back, stitch_count_sleeve,
--   and stitch_count_total to NULL for designs containing autogenerated sample sets
--   (e.g., 12000/7500/500/20000, 2000/7500/700/10200), all-zero records, or
--   legacy demo seeds without genuine admin input or bulk audit logs.
-- ============================================================================

UPDATE designs
SET 
  stitch_count = NULL,
  stitch_count_front = NULL,
  stitch_count_back = NULL,
  stitch_count_sleeve = NULL,
  stitch_count_total = NULL,
  stitch_total_manual = 0
WHERE id NOT IN (
    SELECT DISTINCT design_id 
    FROM stitch_update_log_items 
    WHERE design_id IS NOT NULL
  )
  AND (
    -- 1. Exact sample tuples from automated demo/test scripts
    (stitch_count_front = 12000 AND stitch_count_back = 7500 AND (stitch_count_sleeve IN (500, 5300) OR stitch_count_sleeve IS NULL))
    OR (stitch_count_front = 2000 AND stitch_count_back = 7500 AND (stitch_count_sleeve = 700 OR stitch_count_sleeve IS NULL))
    OR (stitch_count_front = 12500 AND stitch_count_back = 8200)
    OR (stitch_count_front = 5000 AND stitch_count_back = 6000 AND stitch_count_sleeve = 1000)
    OR (stitch_count_front = 10000 AND stitch_count_back = 6000)
    OR (stitch_count_front = 11000 AND stitch_count_back = 6500 AND stitch_count_sleeve = 4500)
    OR (stitch_count_front = 14000 AND stitch_count_back = 7500 AND stitch_count_sleeve = 5300)
    OR (stitch_count_front = 12000 AND stitch_count_back = 8000 AND stitch_count_sleeve = 6000)
    OR (stitch_count_front = 12450 AND stitch_count_back = 18300 AND stitch_count_sleeve = 6200)
    OR (stitch_count_front = 8500 AND stitch_count_back = 12000 AND stitch_count_sleeve = 4100)

    -- 2. Records where all stitch columns are 0
    OR (
      COALESCE(stitch_count_front, 0) = 0 
      AND COALESCE(stitch_count_back, 0) = 0 
      AND COALESCE(stitch_count_sleeve, 0) = 0 
      AND COALESCE(stitch_count_total, 0) = 0 
      AND COALESCE(stitch_count, 0) = 0
    )

    -- 3. Legacy demo seed totals without any component counts entered (and not marked manual)
    OR (
      (stitch_count_front IS NULL OR stitch_count_front = 0)
      AND (stitch_count_back IS NULL OR stitch_count_back = 0)
      AND (stitch_count_sleeve IS NULL OR stitch_count_sleeve = 0)
      AND COALESCE(stitch_total_manual, 0) = 0
    )
  );
